SELECT p.gender, p.age, a.admission_type_id, l.itemid, COUNT(a.hadm_id) AS total_admissions, SUM(CASE WHEN p.dod IS NOT NULL THEN 1 ELSE 0 END) AS total_deaths, CAST(SUM(CASE WHEN p.dod IS NOT NULL THEN 1 ELSE 0 END) AS FLOAT) / NULLIF(COUNT(a.hadm_id), 0) AS mortality_rate FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN labevents l ON a.hadm_id = l.subject_id AND a.stay_id = l.stay_id WHERE p.gender = 'M' AND p.age BETWEEN 87 AND 97 AND a.admission_type_id = 256 AND l.itemid IN (718171, 718172, 718173) GROUP BY p.gender, p.age, a.admission_type_id, l.itemid ORDER BY p.gender, p.age, a.admission_type_id, l.itemid NULLS LAST;